mapper.update:
update sp_supplier_contact set is_primary=1, updated_by=#{userId}
where id=(select id from (select id from sp_supplier_contact
                          where supplier_id=#{supplierId} and deleted=0 order by id limit 1) c)

update sp_supplier_contact
set name=#{name}, phone=#{phone,jdbcType=VARCHAR}, email=#{email,jdbcType=VARCHAR},
    is_primary=1, updated_by=#{userId}
where id=#{id}

update sp_supplier
set contact_name=#{contactName,jdbcType=VARCHAR}, contact_phone=#{contactPhone,jdbcType=VARCHAR},
    email=#{email,jdbcType=VARCHAR}, updated_by=#{userId}
where id=#{supplierId}
